    "id": "scraped-d29e84a734bd",
    "company": "Concern Worldwide",
    "source": "EthioJobs",
    "title": "Programme Manager",
    "location": "Tigray",
    "mode": "Onsite",
    "type": "Full-time Entry Level",
    "experience": "0-2 Years",
